/// <summary>
///  Class to help import data SNAllianceItemGroups from ax2009
/// </summary>
internal final class NDXSNAllianceItemGroupsProcess extends NDXTransferToD365 implements NDXTransferToD365Interface
{
    NDXSNAllianceItemGroups lNDXSNAllianceItemGroups;
    Niedax.AX.TableRecordModels.NDXSNAllianceItemGroups ndxSNAllianceItemGroupsModel;

}

Method.Source:
/// <summary>
/// writes markupAutoTable to database
/// </summary>
/// <param name = "_record">markupAutoTable object</param>
private void writeNDXSNAllianceItemGroups(Niedax.AX.TableRecordModels.TableRecord _record)
{
    System.Exception ex;

    NDXCompany ndxCompany;
    NDXCompanyBE ndxCompanyBE;
    str message = '';
    ndxSNAllianceItemGroupsModel = _record;

    response.Message = strFmt("@NDX:NDXSNAPITransferInfo", ndxSNAllianceItemGroupsModel.D365TableName
                    , ndxSNAllianceItemGroupsModel.ToString()
                    , this.environment);

    if(_record.IsAX2009)
    {
        ndxCompany = ndxSNAllianceItemGroupsModel.Companys;
        ndxCompanyBE = NDXHelperCommon::CompanyId2NDXCompanyBE(ndxCompany);
        ndxSNAllianceItemGroupsModel.Companys = ndxCompanyBE;
    }

    lNDXSNAllianceItemGroups = NDXSNAllianceItemGroups::find(ndxSNAllianceItemGroupsModel.TOSId, ndxSNAllianceItemGroupsModel.Companys, ndxSNAllianceItemGroupsModel.ArtGrp, true);

    try
    {
        //Make only updates on an existing record, since the records are created by determination process in d365
        if(!lNDXSNAllianceItemGroups)
        {
            message = strFmt("@NDX:NDXSNAPITransferInfo1",  this.environment, ndxSNAllianceItemGroupsModel.ToString());
            throw Error(message);
        }
        else
        {
            ttsbegin;
            lNDXSNAllianceItemGroups.Active = ndxSNAllianceItemGroupsModel.Active;
            lNDXSNAllianceItemGroups.ArtGrpMap = ndxSNAllianceItemGroupsModel.ArtGrpMap;
            lNDXSNAllianceItemGroups.write();
            ttscommit;
            response.Success = true;
            response.RecId = lNDXSNAllianceItemGroups.RecId;
        }

    }
    catch(ex)
    {
        message = message + "-" + ex.Message;
        response.RecId = 0;
    }

    response.Message = message;
}

/// <summary>
/// Updates or creates corresponding record
/// </summary>
/// <param name = "_record">record instance</param>
/// <returns>Response</returns>
public Niedax.D365.API.Models.D365_APIResponse writeRecord(Niedax.AX.TableRecordModels.TableRecord _record)
{
    this.writeNDXSNAllianceItemGroups(_record);
    return response;
}
